import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { 
    TrendingUp, Award, Target, CalendarCheck, 
    Flame, Zap, Github, ExternalLink, 
    Clock, CheckCircle, Circle, ArrowRight
} from 'lucide-react';
import axios from 'axios';
import { motion } from 'framer-motion';

const Dashboard = () => {
    const { user, token } = useAuth();
    const [stats, setStats] = useState(null);
    const [loading, setLoading] = useState(true);
    const [tasks, setTasks] = useState([]);
    const [weeklyData, setWeeklyData] = useState([]);

    useEffect(() => {
        if (user) {
            fetchData();
        }
    }, [user]);

    const fetchData = async () => {
        try {
            const tasksRes = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasksRes.data);

            const statsRes = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}/progress`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setStats(statsRes.data);

            const weekRes = await axios.get(
                'http://localhost:8081/api/weekly'
            );
            setWeeklyData(weekRes.data);
            setLoading(false);
        } catch (error) {
            console.error('Failed to fetch data:', error);
            setLoading(false);
        }
    };

    if (loading) {
        return (
            <div className="flex items-center justify-center h-96">
                <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600"></div>
            </div>
        );
    }

    const totalTasks = tasks.length;
    const completedTasks = tasks.filter(t => t.overallCompleted).length;
    const completionRate = totalTasks > 0 ? Math.round((completedTasks / totalTasks) * 100) : 0;
    const totalDays = 31;

    // Calculate streak
    const calculateStreak = () => {
        let streak = 0;
        for (let i = 0; i < 31; i++) {
            const dayTasks = tasks.filter(t => t.day === (31 - i));
            if (dayTasks.length > 0 && dayTasks.every(t => t.overallCompleted)) {
                streak++;
            } else if (i > 0) {
                break;
            }
        }
        return streak;
    };

    const streak = calculateStreak();

    // Get today's tasks
    const today = new Date().getDate();
    const todayTasks = tasks.filter(t => t.day === today);
    const todayCompleted = todayTasks.filter(t => t.overallCompleted).length;

    // Get this week's progress
    const weekTasks = tasks.filter(t => t.day >= 25 && t.day <= 31);
    const weekCompleted = weekTasks.filter(t => t.overallCompleted).length;
    const weekProgress = weekTasks.length > 0 ? Math.round((weekCompleted / weekTasks.length) * 100) : 0;

    const statsCards = [
        {
            title: 'Overall Progress',
            value: `${completionRate}%`,
            icon: TrendingUp,
            color: 'blue',
            bg: 'bg-blue-50',
            text: 'text-blue-600'
        },
        {
            title: 'Days Completed',
            value: `${completedTasks}/${totalDays}`,
            icon: CalendarCheck,
            color: 'green',
            bg: 'bg-green-50',
            text: 'text-green-600'
        },
        {
            title: 'Current Streak',
            value: `${streak} days`,
            icon: Flame,
            color: 'orange',
            bg: 'bg-orange-50',
            text: 'text-orange-600'
        },
        {
            title: 'Today\'s Progress',
            value: `${todayTasks.length > 0 ? Math.round((todayCompleted / todayTasks.length) * 100) : 0}%`,
            icon: Clock,
            color: 'purple',
            bg: 'bg-purple-50',
            text: 'text-purple-600'
        },
    ];

    return (
        <div className="space-y-6">
            {/* Welcome Section */}
            <motion.div 
                initial={{ opacity: 0, y: 20 }}
                animate={{ opacity: 1, y: 0 }}
                className="bg-gradient-to-r from-blue-600 via-purple-600 to-pink-500 rounded-2xl p-8 text-white"
            >
                <div className="flex items-start justify-between flex-wrap gap-4">
                    <div>
                        <h1 className="text-2xl md:text-3xl font-bold mb-2">
                            👋 Welcome back, {user?.fullName?.split(' ')[0] || user?.username}!
                        </h1>
                        <p className="text-blue-100 text-sm md:text-base">
                            Let's finish your tasks today! 🚀
                        </p>
                        <div className="flex flex-wrap gap-2 mt-3">
                            <span className="px-3 py-1 bg-white/20 rounded-full text-xs flex items-center gap-1">
                                <Flame size={14} />
                                {streak} day streak
                            </span>
                            <span className="px-3 py-1 bg-white/20 rounded-full text-xs flex items-center gap-1">
                                <Award size={14} />
                                {completionRate}% complete
                            </span>
                        </div>
                    </div>
                    <div className="flex items-center gap-3">
                        <div className="bg-white/20 px-4 py-2 rounded-xl text-center">
                            <div className="text-2xl font-bold">{completionRate}%</div>
                            <div className="text-xs text-blue-100">Progress</div>
                        </div>
                    </div>
                </div>
            </motion.div>

            {/* Stats Grid */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                {statsCards.map((stat, index) => (
                    <motion.div
                        key={index}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ opacity: 1, y: 0 }}
                        transition={{ delay: index * 0.1 }}
                        className="bg-white rounded-xl shadow-sm border border-gray-100 p-6 hover:shadow-md transition-all"
                    >
                        <div className="flex items-center justify-between">
                            <div>
                                <p className="text-sm text-gray-500">{stat.title}</p>
                                <p className="text-2xl font-bold mt-1">{stat.value}</p>
                            </div>
                            <div className={`${stat.bg} p-3 rounded-lg`}>
                                <stat.icon className={stat.text} size={24} />
                            </div>
                        </div>
                    </motion.div>
                ))}
            </div>

            <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                {/* Weekly Progress */}
                <motion.div 
                    initial={{ opacity: 0, x: -20 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="bg-white rounded-xl shadow-sm border border-gray-100 p-6"
                >
                    <h3 className="font-semibold text-gray-800 mb-4">This Week's Progress</h3>
                    <div className="space-y-4">
                        <div>
                            <div className="flex justify-between text-sm mb-1">
                                <span className="text-gray-600">Week 4 Progress</span>
                                <span className="font-medium text-gray-800">{weekProgress}%</span>
                            </div>
                            <div className="w-full bg-gray-200 rounded-full h-2.5">
                                <div 
                                    className="bg-gradient-to-r from-blue-500 to-purple-500 h-2.5 rounded-full transition-all"
                                    style={{ width: `${weekProgress}%` }}
                                />
                            </div>
                        </div>
                        <div className="grid grid-cols-2 gap-3">
                            <div className="bg-gray-50 rounded-lg p-3 text-center">
                                <p className="text-2xl font-bold text-blue-600">{weekCompleted}</p>
                                <p className="text-xs text-gray-500">Tasks Done</p>
                            </div>
                            <div className="bg-gray-50 rounded-lg p-3 text-center">
                                <p className="text-2xl font-bold text-purple-600">{weekTasks.length}</p>
                                <p className="text-xs text-gray-500">Total Tasks</p>
                            </div>
                        </div>
                    </div>
                </motion.div>

                {/* Today's Tasks */}
                <motion.div 
                    initial={{ opacity: 0, x: 20 }}
                    animate={{ opacity: 1, x: 0 }}
                    className="bg-white rounded-xl shadow-sm border border-gray-100 p-6"
                >
                    <div className="flex items-center justify-between mb-4">
                        <h3 className="font-semibold text-gray-800">Today's Tasks</h3>
                        <span className="text-xs text-gray-500">{todayCompleted}/{todayTasks.length} done</span>
                    </div>
                    {todayTasks.length > 0 ? (
                        <div className="space-y-2">
                            {todayTasks.slice(0, 4).map((task, idx) => {
                                const labels = ['Java', 'LeetCode', 'DSA', 'SQL', 'Project', 'GitHub'];
                                const statuses = [task.javaCompleted, task.leetcodeCompleted, task.dsaCompleted, task.sqlCompleted, task.projectCompleted, task.githubCompleted];
                                return (
                                    <div key={idx} className="flex items-center gap-3 p-2 hover:bg-gray-50 rounded-lg transition">
                                        {statuses[idx] ? 
                                            <CheckCircle size={18} className="text-green-500 flex-shrink-0" /> : 
                                            <Circle size={18} className="text-gray-300 flex-shrink-0" />
                                        }
                                        <span className={`text-sm ${statuses[idx] ? 'text-gray-400 line-through' : 'text-gray-700'}`}>
                                            {labels[idx]}
                                        </span>
                                    </div>
                                );
                            })}
                        </div>
                    ) : (
                        <div className="text-center py-8 text-gray-400">
                            <p className="text-sm">No tasks for today</p>
                            <p className="text-xs">Click on a day in the tracker to start</p>
                        </div>
                    )}
                    <button 
                        onClick={() => window.location.href = '/tracker'}
                        className="mt-4 text-blue-600 text-sm hover:text-blue-800 flex items-center gap-1"
                    >
                        View all tasks <ArrowRight size={16} />
                    </button>
                </motion.div>
            </div>

            {/* Quick Actions */}
            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                <div className="bg-gradient-to-r from-blue-500 to-blue-600 rounded-xl p-6 text-white">
                    <h4 className="font-semibold mb-1">📝 Log Today</h4>
                    <p className="text-blue-100 text-sm mb-3">Track your daily progress</p>
                    <button 
                        onClick={() => window.location.href = '/tracker'}
                        className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm transition"
                    >
                        Go to Tracker →
                    </button>
                </div>
                <div className="bg-gradient-to-r from-purple-500 to-purple-600 rounded-xl p-6 text-white">
                    <h4 className="font-semibold mb-1">📚 Roadmap</h4>
                    <p className="text-purple-100 text-sm mb-3">View your 4-month plan</p>
                    <button 
                        onClick={() => window.location.href = '/weekly-focus'}
                        className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm transition"
                    >
                        View Roadmap →
                    </button>
                </div>
                <div className="bg-gradient-to-r from-green-500 to-green-600 rounded-xl p-6 text-white">
                    <h4 className="font-semibold mb-1">📊 Analytics</h4>
                    <p className="text-green-100 text-sm mb-3">Detailed progress stats</p>
                    <button 
                        onClick={() => window.location.href = '/progress'}
                        className="bg-white/20 hover:bg-white/30 px-4 py-2 rounded-lg text-sm transition"
                    >
                        View Analytics →
                    </button>
                </div>
            </div>
        </div>
    );
};

export default Dashboard;
